import React, { useState, useEffect } from 'react';
import {
  Modal,
  View,
  Text,
  ScrollView,
  Pressable,
  StyleSheet,
  ActivityIndicator,
} from 'react-native';
import { supabase } from '@/config/supabase';
import Markdown from 'react-native-markdown-display';

interface DisclaimerModalProps {
  visible: boolean;
  onAccept: (policyId: string) => void;
  onCancel: () => void;
  testID?: string;
}

interface DisclaimerPolicy {
  id: string;
  policy_type: string;
  version: string;
  title: string;
  content: string;
  effective_date: string;
}

export default function DisclaimerModal({
  visible,
  onAccept,
  onCancel,
  testID = 'disclaimer-modal',
}: DisclaimerModalProps) {
  const [loading, setLoading] = useState(true);
  const [policy, setPolicy] = useState<DisclaimerPolicy | null>(null);
  const [accepted, setAccepted] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (visible) {
      fetchDisclaimer();
      setAccepted(false); // Reset checkbox on open
      setError(null);
    }
  }, [visible]);

  const fetchDisclaimer = async () => {
    try {
      setLoading(true);
      setError(null);

      const { data, error: rpcError } = await supabase.rpc('get_current_policy', {
        p_policy_type: 'liability_disclaimer',
      });

      if (rpcError) throw rpcError;

      if (data && data.length > 0) {
        setPolicy(data[0]);
      } else {
        setError('Liability Disclaimer not available. Please contact support.');
      }
    } catch (err: any) {
      console.error('[DisclaimerModal] Error fetching disclaimer:', err);
      setError('Failed to load disclaimer. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleAcceptPress = () => {
    if (accepted && policy) {
      onAccept(policy.id);
    }
  };

  return (
    <Modal
      visible={visible}
      animationType="slide"
      transparent={false}
      onRequestClose={onCancel}
      testID={testID}
    >
      <View style={styles.container}>
        {/* Header */}
        <View style={styles.header}>
          <Text style={styles.headerTitle}>Liability Disclaimer</Text>
          <Pressable
            onPress={onCancel}
            testID={`${testID}-close-button`}
            accessibilityLabel="Close disclaimer"
          >
            <Text style={styles.closeButton}>✕</Text>
          </Pressable>
        </View>

        {/* Content */}
        {loading ? (
          <View style={styles.loadingContainer}>
            <ActivityIndicator size="large" color="#3B82F6" testID={`${testID}-loading`} />
            <Text style={styles.loadingText}>Loading disclaimer...</Text>
          </View>
        ) : error ? (
          <View style={styles.errorContainer}>
            <Text style={styles.errorIcon}>⚠️</Text>
            <Text style={styles.errorText}>{error}</Text>
            <Pressable style={styles.retryButton} onPress={fetchDisclaimer}>
              <Text style={styles.retryButtonText}>Retry</Text>
            </Pressable>
          </View>
        ) : !policy ? (
          <View style={styles.errorContainer}>
            <Text style={styles.errorText}>Disclaimer not available</Text>
          </View>
        ) : (
          <>
            <ScrollView
              contentContainerStyle={styles.scrollContent}
              testID={`${testID}-scroll-view`}
            >
              <Text style={styles.subtitle}>
                Please read and acknowledge this disclaimer before completing your purchase
              </Text>
              <View style={styles.versionBadge}>
                <Text style={styles.versionText}>Version {policy.version}</Text>
              </View>
              {policy.effective_date && (
                <Text style={styles.effectiveDate}>
                  Effective: {new Date(policy.effective_date).toLocaleDateString()}
                </Text>
              )}

              <View style={styles.contentContainer}>
                <Markdown>{policy.content}</Markdown>
              </View>
            </ScrollView>

            {/* Footer with checkbox and buttons */}
            <View style={styles.footer}>
              <Pressable
                style={styles.checkbox}
                onPress={() => setAccepted(!accepted)}
                testID={`${testID}-checkbox`}
                accessibilityLabel="I have read and understand this disclaimer"
                accessibilityState={{ checked: accepted }}
              >
                <View
                  style={[styles.checkboxInner, accepted && styles.checkboxChecked]}
                >
                  {accepted && <Text style={styles.checkmark}>✓</Text>}
                </View>
                <Text style={styles.checkboxLabel}>
                  I have read and understand this disclaimer
                </Text>
              </Pressable>

              <View style={styles.buttonRow}>
                <Pressable
                  style={[styles.button, styles.cancelButton]}
                  onPress={onCancel}
                  testID={`${testID}-cancel-button`}
                  accessibilityLabel="Cancel purchase"
                >
                  <Text style={styles.cancelButtonText}>Cancel</Text>
                </Pressable>
                <Pressable
                  style={[
                    styles.button,
                    styles.acceptButton,
                    !accepted && styles.buttonDisabled,
                  ]}
                  onPress={handleAcceptPress}
                  disabled={!accepted}
                  testID={`${testID}-accept-button`}
                  accessibilityLabel="Accept and continue"
                  accessibilityState={{ disabled: !accepted }}
                >
                  <Text
                    style={[
                      styles.acceptButtonText,
                      !accepted && styles.buttonTextDisabled,
                    ]}
                  >
                    Accept & Continue
                  </Text>
                </Pressable>
              </View>
            </View>
          </>
        )}
      </View>
    </Modal>
  );
}

