      return {
        icon: '🚫',
        title: 'Wallet Suspended',
        message: 'Your SP wallet has been suspended. Please contact support for assistance.',
        bgColor: '#FEE2E2', // red-100
        iconColor: '#991B1B', // red-800
        textColor: '#7F1D1D', // red-900
      };
    case 'grace_period':
      return {
        icon: '⏳',
        title: 'Grace Period Active',
